CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kv(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY, base_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS variants_base ON variants(base_id);
CREATE TABLE IF NOT EXISTS copies(id TEXT PRIMARY KEY, variant_id TEXT NOT NULL REFERENCES variants(id), cert TEXT UNIQUE, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS copies_variant ON copies(variant_id);
CREATE TABLE IF NOT EXISTS watchlist(variant_id TEXT PRIMARY KEY REFERENCES variants(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS listings(id TEXT PRIMARY KEY, source_id TEXT NOT NULL UNIQUE, data TEXT NOT NULL, checked_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS listing_matches(listing_id TEXT NOT NULL REFERENCES listings(id), variant_id TEXT NOT NULL REFERENCES variants(id), data TEXT NOT NULL, PRIMARY KEY(listing_id,variant_id));
CREATE TABLE IF NOT EXISTS sales(id TEXT PRIMARY KEY, variant_id TEXT NOT NULL REFERENCES variants(id), transaction_key TEXT NOT NULL UNIQUE, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sales_variant ON sales(variant_id);
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, data TEXT NOT NULL, created_at TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS activity(id INTEGER PRIMARY KEY AUTOINCREMENT, time TEXT NOT NULL, message TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires REAL NOT NULL, auth_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS locks(key TEXT PRIMARY KEY, owner TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS scan_log(id TEXT PRIMARY KEY, time TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS images(key TEXT PRIMARY KEY, content BLOB NOT NULL, content_type TEXT NOT NULL);
